#include <vector>
#include <stdexcept>

// Assume T is a custom type that might throw during copy/move
class ThrowingType {
public:
    ThrowingType(int v) : val(v) {}
    int val;
};

void safe_resize(std::vector<ThrowingType>& v, size_t new_size) {
    size_t old_size = v.size();
    try {
        // If this insert (via resize) throws due to reallocation 
        // or element construction failure, the vector guarantees 
        // it will revert to a valid state (strong safety).
        v.resize(new_size, ThrowingType(99)); 
    } catch (const std::exception& e) {
        // The vector is still usable, even if the resize failed.
        // Its size will be either old_size or partially increased.
        // No resources are leaked.
        std::cerr << "Resize failed, vector invariant maintained.\n";
    }
}
